import { Key } from "react";
import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";

import { Tool } from "../../../types/tool";
import { ToolValidationInfo } from "../toolEditor";

import GroupBox from "../../components/GroupBox";
import TextAreaLabeled from "../../components/TextAreaLabeled";
import TextInputLabeled from "../../components/TextInputLabeled";
import TextInputWithButton from "../../components/TextInputWithButton";
import ToolTypeComboBox from "./toolTypeComboBox";

interface MicroflowToolEditorProps {
    tool: Tool;
    validationInfo: ToolValidationInfo;
    onFieldChange: (field: keyof Tool, value: string) => void;
    onSelectDocument: () => void;
    onShowDocument: () => void;
    onToolTypeChange: (key: Key | null) => void;
}

const MicroflowToolEditor: React.FC<MicroflowToolEditorProps> = ({
    tool,
    validationInfo,
    onFieldChange,
    onSelectDocument,
    onShowDocument,
    onToolTypeChange,
}) => {
    return (
        <>
            <GroupBox label="Common">
                <ToolTypeComboBox
                    selectedKey={tool.toolType}
                    validationInfo={validationInfo}
                    onToolTypeChange={onToolTypeChange}
                />
                <TextInputWithButton
                    ariaLabel="Microflow"
                    label="Microflow"
                    value={tool.document.qualifiedName}
                    icon={tool.document.qualifiedName ? <MicroflowIcon /> : undefined}
                    onClick={onSelectDocument}
                    buttonCaption="Select..."
                    buttonCaptionSecondary={tool.document.qualifiedName ? "Show" : undefined}
                    onClickSecondary={tool.document.qualifiedName ? onShowDocument : undefined}
                    validate={() => validationInfo.isValidDocument}
                />
            </GroupBox>
            <GroupBox label="Naming">
                <TextInputLabeled
                    label="Name"
                    ariaLabel="Name"
                    value={tool.name}
                    onChange={(value: string) => onFieldChange("name", value)}
                    validate={() => validationInfo.isValidName}
                />
                <TextAreaLabeled
                    label="Description"
                    ariaLabel="Description"
                    value={tool.description}
                    onChange={(value: string) => onFieldChange("description", value)}
                    validate={() => validationInfo.isValidDescription}
                />
            </GroupBox>
        </>
    );
};

export default MicroflowToolEditor;
