import { Key, useCallback, useEffect, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";

import { useDialogShortcuts } from "../../hooks/useDialogShortcuts";

import { Agent } from "../../types/agent";
import { Tool, ToolType } from "../../types/tool";

import DialogFooter from "../components/DialogFooter";
import { ContentColumn, PageContainerDialog, PageContent } from "../components/PageContainers";

import { handleSelectDocument, handleValidateTool } from "./toolHandlers";

import { ToolTypes } from "../../constants/mcp";
import { consumedMCPServiceDocumentTypeId } from "../../main";
import { handleShowCustomBlobDocument } from "../../utils/customBlobDocumentUtils";
import { handleShowMicroflow } from "../../utils/microflowUtils";
import { createNewTool } from "../../utils/toolUtils";
import MCPToolEditor from "./tooltypes/mcpToolEditor";
import MicroflowToolEditor from "./tooltypes/microflowToolEditor";

interface ToolEditorProps {
    studioPro: StudioProApi;
    initialTool?: Tool;
    agent: Agent;
    onClose: (result: Tool | null) => void;
}

export type ToolValidationInfo = {
    isValidName: true | string;
    isValidDescription: true | string;
    isValidDocument: true | string;
    isValidType: true | string;
};

const initialValidationInfo: ToolValidationInfo = {
    isValidName: true,
    isValidDescription: true,
    isValidDocument: true,
    isValidType: true,
};

const fieldToValidationKey: Partial<Record<keyof Tool, keyof ToolValidationInfo>> = {
    name: "isValidName",
    description: "isValidDescription",
    toolType: "isValidType",
    document: "isValidDocument",
};

const ToolEditor: React.FC<ToolEditorProps> = ({ initialTool, studioPro, agent, onClose }) => {
    const [tool, setTool] = useState(initialTool || createNewTool());
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);

    const validateTool = useCallback(
        async (tool: Tool): Promise<ToolValidationInfo> => {
            return {
                isValidName: await handleValidateTool("name", tool, agent, studioPro),
                isValidDescription: await handleValidateTool("description", tool, agent, studioPro),
                isValidDocument: await handleValidateTool("document", tool, agent, studioPro),
                isValidType: await handleValidateTool("toolType", tool, agent, studioPro),
            };
        },
        [studioPro, agent]
    );

    // Validate if initial tool is provided
    useEffect(() => {
        if (initialTool && initialTool.name) {
            validateTool(initialTool).then((validationResult) => {
                setValidationInfo(validationResult);
            });
        }
    }, [initialTool, validateTool]);

    const handleOk = async () => {
        // Validate all fields when OK is clicked
        const validationResult = await validateTool(tool);
        setValidationInfo(validationResult);

        const validationErrors = Object.values(validationResult).some((value) => value !== true);
        if (!validationErrors) {
            // Clear name and description for MCP tools since they are provided by the MCP server; this is done only at save time to allow users to switch back and forth without clearing their previous input
            const finalTool = tool.toolType === ToolTypes.MCP ? { ...tool, name: "", description: "" } : tool;
            onClose(finalTool);
        }
    };

    const handleCancel = () => {
        onClose(null);
    };

    useDialogShortcuts(handleCancel, handleOk);

    const handleHelp = () => {
        if (tool.toolType === ToolTypes.Microflow) {
            window.open(
                "https://docs.mendix.com/appstore/modules/genai/genai-for-mx/agent-commons/#adding-microflows-as-tools",
                "_blank",
                "noopener,noreferrer"
            );
        } else if (tool.toolType === ToolTypes.MCP) {
            window.open(
                "https://docs.mendix.com/appstore/modules/genai/genai-for-mx/agent-commons/#adding-tools-from-mcp-servers",
                "_blank",
                "noopener,noreferrer"
            );
        } else {
            window.open(
                "https://docs.mendix.com/appstore/modules/genai/genai-for-mx/agent-commons/#adding-tools",
                "_blank",
                "noopener,noreferrer"
            );
        }
    };

    const validateOnChange = async (field: keyof Tool, updatedTool: Tool) => {
        const validationKey = fieldToValidationKey[field];

        //rerun validation only if the field is currently invalid; otherwise validation only run on OK click to avoid excessive validation while user is editing
        if (validationKey && validationInfo[validationKey] !== true) {
            const validationResult = await handleValidateTool(field, updatedTool, agent, studioPro);
            setValidationInfo((prev) => ({ ...prev, [validationKey]: validationResult }));
        }
    };

    const handleFieldChange = (field: keyof Tool, value: string) => {
        const updatedTool = { ...tool, [field]: value };
        setTool(updatedTool);
        validateOnChange(field, updatedTool);
    };

    const selectDocument = async () => {
        const document = await handleSelectDocument(
            studioPro,
            tool.toolType === ToolTypes.MCP ? consumedMCPServiceDocumentTypeId : "Microflows$Microflow"
        );
        if (document) {
            const updatedTool = { ...tool, document };
            setTool(updatedTool);
            validateOnChange("document", updatedTool);
        }
    };

    const showDocument = () => {
        if (tool.document?.documentId) {
            if (tool.toolType === ToolTypes.Microflow && tool.document.documentId) {
                handleShowMicroflow(studioPro, tool.document);
            } else if (tool.toolType === ToolTypes.MCP && tool.document.documentId) {
                handleShowCustomBlobDocument(studioPro, tool.document);
            }
        }
    };

    const onToolTypeChange = (key: Key | null) => {
        const updatedTool: Tool = {
            ...tool,
            toolType: key as ToolType,
            document: {
                documentId: "",
                qualifiedName: "",
            },
        };
        setTool(updatedTool);
        validateOnChange("toolType", updatedTool);
    };

    return (
        <PageContainerDialog>
            <PageContent>
                <ContentColumn>
                    {tool.toolType === ToolTypes.Microflow ? (
                        <MicroflowToolEditor
                            tool={tool}
                            validationInfo={validationInfo}
                            onFieldChange={handleFieldChange}
                            onSelectDocument={selectDocument}
                            onShowDocument={showDocument}
                            onToolTypeChange={onToolTypeChange}
                        />
                    ) : (
                        <MCPToolEditor
                            tool={tool}
                            validationInfo={validationInfo}
                            onSelectDocument={selectDocument}
                            onShowDocument={showDocument}
                            onToolTypeChange={onToolTypeChange}
                        />
                    )}
                </ContentColumn>
            </PageContent>
            <DialogFooter onOk={handleOk} onCancel={handleCancel} onHelp={handleHelp} />
        </PageContainerDialog>
    );
};

export default ToolEditor;
